def update_issue(id, addition, close=False):
    global text
    match=re.search(r'^### '+re.escape(id)+r'\n[\s\S]*?(?=^### |\Z)',text,re.M)
    assert match,id
    body=match.group()
    if close:
        assert 'Статус: **открыта**' in body
        body=body.replace('Статус: **открыта**','Статус: **проверена**',1)
    body=body.rstrip()+'\n- Дополнение LOG-20261019-02: '+addition+' '+proof+'\n\n'
    text=text[:match.start()]+body+text[match.end():]

